TRANSLATIONS = {"en": EN}

# Per-platform payloads: {lang: {platform: {h1, tagline, placeholder,
# steps, sections, faq}}}. "sections" holds only the platform-specific
# sections; the view appends the shared personal-use section last.
PLATFORM_TRANSLATIONS = {}

HOME_FAQ_KEYS = [("hfaq1_q", "hfaq1_a"), ("hfaq2_q", "hfaq2_a"),
                 ("hfaq3_q", "hfaq3_a"), ("hfaq4_q", "hfaq4_a"),
                 ("hfaq5_q", "hfaq5_a")]


def is_valid(code):
    return code in LANG_CODES


def get_strings(code):
    """Shared UI strings for a language, merged over English."""
    merged = dict(EN)
    if code != DEFAULT_LANG:
        merged.update(TRANSLATIONS.get(code, {}))
    return merged


def home_faq(code):
    t = get_strings(code)
    return [(t[q], t[a]) for q, a in HOME_FAQ_KEYS]


def platform_strings(code, platform):
    """Translated platform payload for (language, platform); {} when
    the language has none — the caller then keeps the English data."""
    if code == DEFAULT_LANG:
        return {}
    return PLATFORM_TRANSLATIONS.get(code, {}).get(platform, {})


def language_name(code):
    for lang in LANGUAGES:
        if lang["code"] == code:
            return lang["name"]
    return "English"

