            ("தனிப்பட்ட Facebook வீடியோவை ஏன் பதிவிறக்க முடியாது?", "தனிப்பட்ட மற்றும் நண்பர்களுக்கு மட்டுமான வீடியோக்கள் அவற்றைப் பார்க்க அனுமதியுடன் உள்நுழைந்தவர்களுக்கு மட்டுமே தெரியும். QGrab-க்கு அவற்றுக்கான அணுகல் இல்லை, எனவே பொது வீடியோக்களை மட்டுமே பதிவிறக்க முடியும்."),
